def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])
    nums = list(map(int, lines[1].split()))

    def is_gp(seq):
        length = len(seq)
        if length <= 2:
            return True
        if all(x == 0 for x in seq):
            return True
        if seq[0] == 0:
            return False

        # for GP with non-zero start, check that each consecutive ratio is constant
        # Using cross-multiplication: seq[i] / seq[i-1] = seq[1] / seq[0] => seq[i] * seq[0] = seq[i-1] * seq[1]
        for i in range(2, length):
            if seq[0] * seq[i] != seq[i-1] * seq[1]:
                return False

        return True

    # Check if original sequence is a GP
    if is_gp(nums):
        return "0"

    # Try removing each single element
    for i in range(n):
        new_nums = nums[:i] + nums[i+1:]
        if is_gp(new_nums):
            return "1"

    return "2"
