    for topic in range(1, n + 1):
        prereq = p[topic - 1]
        if prereq != 0:
            if prereq not in topic_chain:
                return '0\n'
            else:
                p_chain = topic_chain[prereq]
                t_chain = topic_chain[topic]

                if p_chain != t_chain:
                    chain_deps[p_chain].add(t_chain)
                    chain_in_degree[t_chain] += 1
                else:
                    if topic_pos[topic] <= topic_pos[prereq]:
                        return '0\n'  # Invalid within-chain order

    # Topological sort
    chain_in_degree = {i: 0 for i in range(len(chains))}

    # Rebuild dependencies cleanly
    chain_deps = defaultdict(set)
    chain_in_degree = {}

    for chain_idx in range(len(chains)):
        chain_in_degree[chain_idx] = 0

    for topic in range(1, n + 1):
        prereq = p[topic - 1]
        if prereq != 0:
            p_chain = topic_chain[prereq]
            t_chain = topic_chain[topic]

            if p_chain != t_chain:
                if t_chain not in chain_deps[p_chain]:
                    chain_deps[p_chain].add(t_chain)
                    chain_in_degree[t_chain] = chain_in_degree.get(t_chain, 0) + 1

    # Find cycles and build final order
    queue = deque([i for i in range(len(chains)) if chain_in_degree[i] == 0])

    result = []
    placed = []

    while queue:
        node = queue.popleft()
        if node not in placed:
            placed.append(node)

        result.extend(chains[node])

        for neighbor in chain_deps[node]:
            chain_in_degree[neighbor] -= 1
            if chain_in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(placed) < len(chains):
        return '0\n'

    return f"{' '.join(map(str, result))}\n"
