    """Find flip sequence using BFS"""
    visited = {frozenset(initial_diagonals)}
    queue = deque()

    start = list(initial_diagonals)
    queue.append((frozenset(start), []))

    while queue:
        current, path = queue.popleft()

        if current == frozenset(goal_diagonals):
            return path

        if len(path) > 20000:
