        # Build adjacency
        adj = [[] for _ in range(n + 1)]
        for d in current:
            a, b = d
            adj[a].append(b)
            adj[b].append(a)

        # Try flipping each diagonal
        flipped_against = set()
        for i in range(len(current)):
            d = sorted(current[i])
            a, b = d

            if d in flipped_against:
                continue

            # Find the two triangles sharing diagonal a-b
            # In a valid triangulation, diagonal a-b is shared by exactly 2 triangles
            # So there exist exactly 2 vertices c and d forming triangles (a,b,c) and (a,b,d)
            # The new diagonal will be c-d

            other_vertices = set()
            for v in range(1, n + 1):
                # Vertex v forms triangle with a and b if both (a,v) and (b,v) are in current
                if v != a and v != b:
                    if (a, v) in current and (b, v) in current:
                        other_vertices.add(v)
                # Also check if the sorted pair exists
                elif v != a and v != b:
                    if tuple(sorted((a, v))) in current and tuple(sorted((b, v))) in current:
