    coeff = [0.0] * (n + 1)
    const_node = [0.0] * (n + 1)
    visited = [False] * (n + 1)
    num_constraints_violated = 0

    def dfs(u, r_id, c_val, p_val):
        nonlocal num_constraints_violated
        if num_constraints_violated > 0:
            return
        visited[u] = True
        ref[u] = r_id
        coeff[u] = c_val
        const_node[u] = p_val

        for v, edge_type in adj[u]:
            if not visited[v]:
                # x[v] = edge_type - x[u]
                # x[v] = edge_type - (c_u * ref + p_u)
                # x[v] = (-c_u) * ref + (edge_type - p_u)
                dfs(v, r_id, -c_val, edge_type - p_val)
                if num_constraints_violated > 0:
                    return
            elif ref[u] == ref[v]:
                # Check consistency: x[u] + x[v] should equal edge_type
                expected = edge_type - (coeff[u] * coeff[v] + const_node[v])
                if abs(coeff[u] + coeff[v] - coeff[v]) > 1e-9 or abs(coeff[u] + coeff[v] - (coeff[u] + coeff[v])) > 1e-9:
                    # Check if edge constraint is violated
                    actual_sum = coeff[u] + coeff[v]
                    if abs(actual_sum) > 0.001:
                        if abs(p_val + const_node[v] - edge_type) > 1e-9:
                            num_constraints_violated += 1
                            return
                    else:
                        if abs(p_val + const_node[v] - edge_type) > 1e-9:
                            num_constraints_violated += 1
                            return

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, i, 1.0, 0.0)
            if num_constraints_violated > 0:
                break

    if num_constraints_violated > 0:
        return "NO"

    # Calculate total absolute values and find optimal reference values
    total_absolute = 0
    sum_coeff = 0.0
    sum_const = 0.0

    for i in range(1, n + 1):
        total_absolute += abs(coeff[i])
        sum_coeff += coeff[i]
        sum_const += const_node[i]

    # For each component, find optimal reference value
    component_optimal = []

    # Find components and their constraints
    component_nodes = {}
    for i in range(1, n + 1):
        if ref[i] == 0:
            component_nodes[i] = [i]
            for j in range(1, n + 1):
                if ref[j] != 0 and ref[j] == i:
                    component_nodes[i].append(j)

    # Calculate minimum for entire system
    all_coeff_nonzero = all(abs(coeff[i]) > 1e-9 for i in range(1, n + 1))

    if sum_coeff == 0:
        # Reference value doesn't affect anything
        reference_value = 0
    else:
        # Find optimal reference value to minimize sum of absolute values
        reference_value = sum_const / sum_coeff

    # Calculate actual values
    sol = []
    for i in range(1, n + 1):
        if ref[i] == 0:
            sol.append("0.00")
        else:
            val = coeff[i] * reference_value + const_node[i]
            sol.append(f"{val:.8f}")

    return "YES\n" + " ".join(sol)
