def solution(s):
    lines = s.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        operations = lines[idx]
        idx += 1

        # Process all operations
        for op in operations:
            if op == 'R':
                # Shift columns right: a_{i,j} <- a_{i, (j-2)%n + 1}
                # Which means new col j gets value from old col (j-1)%n
                new_matrix = [[0] * n for _ in range(n)]
                for i in range(n):
                    for j in range(n):
                        new_matrix[i][j] = matrix[i][((j - 2 + n) % n)]
                matrix = new_matrix
            elif op == 'L':
                # Shift columns left: a_{i,j} <- a_{i, j%n + 1}
                # Which means new col j gets value from old col j+1 (mod n)
                for i in range(n):
                    for j in range(n):
                        old_j = (j + 1) % n
                        matrix[i][j] = matrix[i][old_j]
            elif op == 'D':
                # Shift rows down: a_{i,j} <- a_{(i-2)%n + 1, j}
                # Which means new row i gets value from old row (i-1)%n
                for i in range(n):
                    for j in range(n):
                        old_i = (i + 1) % n
                        matrix[i][j] = matrix[old_i][j]
            elif op == 'U':  # Shift rows up
                # a_{i,j} <- a_{i%n + 1, j} means new row i gets value from old row i-1
                for i in range(n):
                    for j in range(n):
                        old_i = (i - 1 + n) % n
                        matrix[i][j] = matrix[old_i][j]
            elif op == 'I':
                # Inverse each row: if row is [p1, p2, ..., pn], inverse q where p[q[j]] = j+1
                for i in range(n):
                    row = matrix[i]
                    inv_row = [0] * n
                    for j in range(n):
                        inv_row[row[j] - 1] = j + 1
                    matrix[i] = inv_row
            elif op == 'C':
                # Inverse each column: for each column, find where each value comes from
                temp = [[0] * n for _ in range(n)]
                for j in range(n):
                    col = [matrix[i][j] for i in range(n)]
                    inv_col = [0] * n
                    for i in range(n):
                        inv_col[col[i] - 1] = i
                    for i in range(n):
                        temp[i][j] = matrix[inv_col[i]][j]
                matrix = temp

        # Build output
        output_lines = []
        for i in range(n):
            output_lines.append(' '.join(map(str, matrix[i])))
        results.append('\n'.join(output_lines))

    return '\n\n'.join(results)
