def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return "0"

    n = int(lines[0])
    coords = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        coords.append((int(parts[0]), int(parts[1])))

    MOD = 1000000007

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def ccw(a, b, c):
        return (c[1] - b[1]) * (a[0] - b[0]) - (a[1] - b[1]) * (c[0] - b[0])

    def intersect_strict(p1, p2, p3, p4):
        d1 = ccw(p3, p4, p1)
        d2 = ccw(p3, p4, p2)
        d3 = ccw(p1, p2, p3)
        d4 = ccw(p1, p2, p4)
        return ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
               ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0))

    def is_valid_diagonal(v1, v2):
        if abs(v1 - v2) == 1 or v1 == 0 and v2 == n - 1:
            return True

        for u in range(n):
            v = (u + 1) % n
            if u == v1 or u == v2 or v == v1 or v == v2:
                continue
            if intersect_strict(coords[v1], coords[v2], coords[u], coords[v]):
                return False
        return True

    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][(i + 1) % n] = 1

    for length in range(2, n):
        for i in range(n):
            j = (i + length) % n
            if i >= j:
                continue

            dp[i][j] = 0
            k = i + 1
            while k < j:
                if is_valid_diagonal(i, k) and is_valid_diagonal(k, j):
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD
                k += 1

    return str(dp[0][n - 1] % MOD)
