        elif ch == 'L':
            cur_x -= 1
        elif ch == 'R':
            cur_x += 1
        DDX[i + 1] = cur_x
        DDY[i + 1] = cur_y

    # Check for infinite case when net displacement is zero
    if DDX[n] == 0 and DDY[n] == 0:
        # Pattern cycles, need to check if all cells can hit walls
        # For infinite case, check if there exists a position that never exits
        for r in range(1, h + 1):
            for c in range(1, w + 1):
                max_x = max(DDX)
                min_x = min(DDX)
                max_y = max(DDY)
                min_y = min(DDY)
                if c + max_x <= w and c + min_x >= 1 and r + max_y <= h and r + min_y >= 1:
                    return "-1\n"

    # Precompute first occurrence of each displacement for efficiency
    first_dx = {}
    first_dy = {}
    for i in range(n + 1):
        dx, dy = DDX[i], DDY[i]
        if dx not in first_dx:
            first_dx[dx] = i
        if dy not in first_dy:
            first_dy[dy] = i

    total = 0

    # For each cell, find minimum steps to hit any wall
    # Use efficient lookup instead of iterating all steps
    for r in range(1, h + 1):
        for c in range(1, w + 1):
            # Find minimum steps to hit horizontal wall
            # Need c + DDX[k] < 1 or c + DDX[k] > w
            # i.e., DDX[k] < 1 - c or DDX[k] > w + 1 - c

            min_time = n + 1

            # Check all relevant displacement values via lookup
            for dx in first_dx:
                if dx < 1 - c or dx > w + 1 - c:
                    t = first_dx[dx]
                    min_time = min(min_time, t)

            # Check all relevant displacement values via lookup
            for dy in first_dy:
                if dy < 1 - r or dy > h + 1 - r:
                    t = first_dy[dy]
                    min_time = min(min_time, t)

            total = (total + min_time) % MOD

    return str(total) + "\n"

