def solution(input_str):
    lines = input_str.split('\n')
    n, k = map(int, lines[0].split())
    s = list(lines[1])

    OFFSET = k + 1  # Offset for handling negative balances in array indexing
    num_balances = 2 * k + 1  # Ranges from -k to k

    # dp[i][balance_index] = can we reach position i with balance after applying up to i moves?
    dp = [[False] * num_balances for _ in range(n + 1)]

    # parent[i][balance_index] stores (move_char, prev_balance) for reconstruction
    parent = [[None] * num_balances for _ in range(n + 1)]

    # Start at balance 0 before any moves
    start_idx = 0 + OFFSET
    dp[0][start_idx] = True

    for i in range(n):
        char = s[i]
        for b in range(-k, k + 1):
            if not dp[i][b + OFFSET]:
                continue

            # Determine which moves are allowed
            allowed_moves = []
            if char == 'D' or char == '?':
                allowed_moves.append('D')
            if char == 'W' or char == '?':
                allowed_moves.append('W')
            if char == 'L' or char == '?':
                allowed_moves.append('L')

            for move in allowed_moves:
                if move == 'D':
                    nb = b
                elif move == 'W':
                    nb = b + 1
                elif move == 'L':
                    nb = b - 1

                # Constraint: Before the last hand, abs(balance) must be < k
                # After the last hand, abs(balance) must be exactly k
                if i < n - 1:
                    # Not the final position - must stay strictly within bounds
                    if abs(nb) >= k:
                        continue
                else:
                    # Final position - must reach exactly k
                    if abs(nb) != k:
                        continue

                nb_idx = nb + OFFSET
                if not dp[i+1][nb_idx]:
                    dp[i+1][nb_idx] = True
                    parent[i+1][nb_idx] = (move, b)

    # Check if any valid final state exists (balance = k or balance = -k)
    final_pos_idx = k + OFFSET
    final_neg_idx = -k + OFFSET

    reachable_final = []
    if dp[n][final_pos_idx]:
        reachable_final.append(k)
    if dp[n][final_neg_idx]:
        reachable_final.append(-k)

    if not reachable_final:
        return "NO"

    # Reconstruct the sequence by backtracking from a valid final state
    result = [''] * n
    for target_balance in reachable_final:
        idx = target_balance + OFFSET
        b = target_balance
        valid_path = True

        for i in range(n, 0, -1):
            move, prev_b = parent[i][idx]
            result[i-1] = move
            b = prev_b
            if b < -k or b > k:
                valid_path = False
                break
            idx = b + OFFSET

        if valid_path:
            return ''.join(result)

    return "NO"
