import sys
from collections import defaultdict
from math import gcd

sys.setrecursionlimit(500000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    n, m = map(int, lines[idx].split())
    idx += 1

    graph = defaultdict(list)
    for _ in range(m):
        a, b, l = map(int, lines[idx].split())
        idx += 1
        graph[a].append((b, l))

    q = int(lines[idx])
    idx += 1

    queries = []
    for _ in range(q):
        v, s, t = map(int, lines[idx].split())
        idx += 1
        queries.append((v, s, t))

    visited = [False] * (n + 1)
    dist_map = {}
    parent_map = {}
    node_gcd = {i: 0 for i in range(1, n + 1)}

    def dfs(u, d, root):
        visited[u] = True
        dist_map[u] = d
        parent_map[u] = root

        for v, w in graph[u]:
            if not visited[v]:
                dfs(v, d + w, u)
            elif v != parent_map[u] and v in dist_map:
                # Back-edge: cycle from v -> ... -> u -> v
                cycle_len = dist_map[u] - dist_map[v] - w
                cycle_len = abs(cycle_len)
                if node_gcd[u] == 0:
                    node_gcd[u] = cycle_len if cycle_len > 0 else 0
                else:
                    node_gcd[u] = gcd(node_gcd[u], cycle_len)
                # Also update ancestor's GCD since same cycle affects us
                if node_gcd[v] == 0 or cycle_len > 0:
                    node_gcd[v] = gcd(node_gcd[v], cycle_len)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, 0, i)

    results = []
    for v, s, t in queries:
        g = node_gcd[v] if v in node_gcd else 0

        if s == 0:
            results.append("YES")
        elif g == 0:
            results.append("NO")
        else:
            # Need (k * g) % t = (t - s) % t for some k
            # Equivalently: gcd(g, t) must divide (t - s)
            g_t = gcd(g, t)
            if (t - s) % g_t == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n'.join(results)

