    lee_starts_next = True

    for i, (s, e) in enumerate(rounds):
        cache = eval_game.cache_clear
        cache()

        can_win = eval_game(s, e)

        if lee_starts_next:
            lee_won = can_win
        else:
            lee_won = not can_win

        if not lee_won:
            lee_wins_all = False
        if lee_won:
            lee_loses_all = False

        lee_starts_next = not lee_won

    return f"{1 if lee_wins_all else 0} {1 if lee_loses_all else 0}\n"
