def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if idx >= len(lines):
        return ""

    try:
        t = int(lines[idx])
        idx += 1
    except ValueError:
        return ""

    test_case_outputs = []

    for _ in range(t):
        # Skip empty lines between test cases
        while idx < len(lines) and lines[idx].strip() == '':
            idx += 1
        if idx >= len(lines):
            break

        try:
            n = int(lines[idx])
            idx += 1
        except ValueError:
            break

        wires = []
        for _ in range(n):
            while idx < len(lines) and lines[idx].strip() == '':
                idx += 1
            if idx >= len(lines):
                break
            parts = lines[idx].split()
            x, y = int(parts[0]), int(parts[1])
            idx += 1
            wires.append((x, y))

        if n <= 1:
            test_case_outputs.append("0")
            continue

        # Union-Find for wires
        parent = list(range(n))
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py

        # Group wires by contact points
        point_to_wires = defaultdict(list)
        for i, (x, y) in enumerate(wires):
            point_to_wires[x].append(i)
            point_to_wires[y].append(i)

        # Union all wires sharing the same contact point
        for point, w_list in point_to_wires.items():
            if len(w_list) > 1:
                first = w_list[0]
                for i in range(1, len(w_list)):
                    union(first, w_list[i])

        # Find connected components
        roots = {}
        for i in range(n):
            r = find(i)
            if r not in roots:
                roots[r] = []
            roots[r].append(i)

        num_comps = len(roots)
        output_lines = [str(num_comps - 1)]

        if num_comps > 1:
            common = 3000000000  # Use a very large number that won't be in input

            # Select one representative from first component (no change)
            # Process other components by changing one endpoint to common

            first_comp_members = roots[list(roots.keys())[0]]
            first_comp_wire_idx = first_comp_members[0]

            for r, members in roots.items():
                # Skip the first component
                if r == first_comp_wire_idx:
                    continue

                wire_idx = members[0]
