                else:
                    old_endpoint = y
                    new_endpoint = common

                output_lines.append(f"{wire_idx + 1} {old_endpoint} {new_endpoint}")

        test_case_outputs.append("\n".join(output_lines))

    return "\n".join(test_case_outputs)


